const VERSION='0.5.5';
const collections=new CollectionWindow();
const installation=createInstallation({onChange:updateInstallControls});
let syncUI;
const ICONS={gear:'<path d="m9 3-.5 2.5-1.4.8-2.4-.8-2.4 4.2 1.9 1.7v1.6l-1.9 1.7 2.4 4.2 2.4-.8 1.4.8L9 21h6l.5-2.5 1.4-.8 2.4.8 2.4-4.2-1.9-1.7v-1.6l1.9-1.7-2.4-4.2-2.4.8-1.4-.8L15 3Z"/><circle cx="12" cy="12" r="3"/>',cloud:'<path d="M6.2 18h11a4.3 4.3 0 0 0 .2-8.6A5.9 5.9 0 0 0 6 10.5 3.8 3.8 0 0 0 6.2 18Z"/>',grip:'<circle cx="8" cy="5" r="1"/><circle cx="16" cy="5" r="1"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/><circle cx="8" cy="19" r="1"/><circle cx="16" cy="19" r="1"/>',resume:'<path d="M4 9a8 8 0 1 1 .6 7M4 4v5h5"/>',appearance:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1.4-3.4 1.5 1.5 0 0 1 1.1-2.6H17a4 4 0 0 0 4-4 9 9 0 0 0-9-8Z"/><circle cx="7.5" cy="11" r=".7"/><circle cx="10" cy="7.5" r=".7"/><circle cx="14.5" cy="7.5" r=".7"/><circle cx="17" cy="11" r=".7"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h.01M3 12h.01M3 18h.01"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--glass-strong)"/><circle cx="15" cy="17" r="3" fill="var(--glass-strong)"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',edit:'<path d="m15 5 4 4M4 20l4-1 12-12a2.8 2.8 0 0 0-4-4L4 15z"/>',leaf:'<path d="M20 4C8 3 3 8 6 15c7 4 14-1 14-11Z"/><path d="M4 21 15 10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',box:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 9h8M8 13h5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',device:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',up:'<path d="m6 14 6-6 6 6"/>',down:'<path d="m6 10 6 6 6-6"/>',flag:'<path d="M5 21V4c5-3 9 3 14 0v10c-5 3-9-3-14 0"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>'};
const icon=n=>`<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.box}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const areaStyle=a=>`style="--area-color:${a?.color||COLORS[0]}"`;
const repo=new Repository(localStorage);
let fatal='',state,deviceId,ui={accent:'teal',visualVersion:3,motion:'subtle'};
try{state=repo.load()}catch(e){fatal=e.message;state=initialState()}
try{const savedUI=JSON.parse(localStorage.getItem(UI_KEY)||'{}');ui={...ui,...savedUI};if(Object.hasOwn(ui,'theme')){delete ui.theme;localStorage.setItem(UI_KEY,JSON.stringify(ui))}if(savedUI.visualVersion!==3){ui.accent='teal';ui.visualVersion=3;localStorage.setItem(UI_KEY,JSON.stringify(ui))}deviceId=localStorage.getItem(DEVICE_KEY);if(!deviceId){deviceId=uid();localStorage.setItem(DEVICE_KEY,deviceId)}}catch{deviceId=uid()}
let page='plan',area='all',status='all',scope='all',query='',priorityFilter='all',sortOrder=ui.order||'manual',moreFilters=false,toastTimer,returnFocus,modalDirty=false,lastDeletion=null;
let groupBy=['area','priority','none'].includes(ui.groupBy)?ui.groupBy:'none',layout=ui.layout==='cards'?'cards':'compact';
document.documentElement.dataset.accent=ui.accent||'teal';
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
function motionEnabled(){return ui.motion!=='off'&&!motionPreference.matches}
function syncVisualMotion(){const root=document.documentElement;root.dataset.motion=motionEnabled()?'subtle':'off';const typing=document.activeElement?.matches('input,textarea,select');root.dataset.pageHidden=String(document.hidden);root.dataset.ambientPaused=String(!motionEnabled()||document.hidden||!!typing||!!document.querySelector('dialog[open]'))}
function enterView(){if(!motionEnabled())return;const content=document.querySelector('#task-results')||document.querySelector('main');content?.animate?.([{opacity:.94,transform:'translate3d(0,3px,0)'},{opacity:1,transform:'translate3d(0,0,0)'}],{duration:180,easing:'cubic-bezier(.2,.7,.3,1)'})}
const today=()=>localDate();
const dateLabel=(date,opts={day:'numeric',month:'short'})=>new Date(date+'T12:00:00').toLocaleDateString('pt-BR',opts).replace('.','');
const statusLabel={pending:'Pendente',doing:'Em andamento',done:'Concluído',canceled:'Cancelado'};
function saveUI(){try{localStorage.setItem(UI_KEY,JSON.stringify(ui))}catch{toast('A preferência de aparência vale apenas nesta sessão.')}}
function toast(message,action){clearTimeout(toastTimer);const el=document.querySelector('#toasts');el.innerHTML=`<div class="toast"><span>${esc(message)}</span>${action?`<button id="toast-action">${esc(action.label)}</button>`:''}</div>`;if(action)document.querySelector('#toast-action').onclick=()=>{el.innerHTML='';action.run()};toastTimer=setTimeout(()=>el.innerHTML='',action?9000:5500)}
async function mutate(operation,message,{replace=null}={}){try{state=await repo.commit(operation,{replace});fatal='';syncUI?.localSaved();render();syncUI?.changed();if(message)toast(message);return true}catch(e){if(e.code==='LOCAL_STORAGE_FAILED')syncUI?.localFailure(e.message);const err=document.querySelector('.formerror');if(err)err.textContent=e.message;else toast(e.message);return false}}
function navButton(p,label,i){return `<button data-action="page" data-page="${p}" class="view-tab ${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`}
function render(){
  document.title=({plan:'Planejamento',agenda:'Cronograma',areas:'Áreas',settings:'Configurações'})[page]+' · Retomar';
  const areas=activeAreas(state);if(area!=='all'&&!areas.some(a=>a.id===area))area='all';
  document.querySelector('#app').innerHTML=`<div class="tracker-shell" data-page="${page}"><header class="masthead"><div class="brand"><span class="brandmark">${icon('resume')}</span><div><span class="brandname">Retomar</span><span class="brandcaption">Planejamento de vida</span></div></div><div class="header-actions">${page==='plan'||page==='agenda'?`<button class="btn primary desktop-add" data-action="new">${icon('plus')} Adicionar item</button>`:''}<div class="header-tools">${syncUI?.header()||''}<button type="button" class="settings-trigger ${page==='settings'?'selected':''}" data-action="page" data-page="settings" aria-label="Configurações" title="Configurações" ${page==='settings'?'aria-current="page"':''}>${icon('gear')}</button></div></div></header><nav class="viewnav" aria-label="Visualização do planejamento">${navButton('plan','Planejamento','grid')}${navButton('agenda','Cronograma','calendar')}</nav><main>${fatal?`<div class="errorbanner" role="alert">${esc(fatal)}<br>Os dados existentes serão preservados. <button data-action="raw">Baixar cópia para recuperação</button> <button data-action="page" data-page="settings">Restaurar backup</button></div>`:''}${page==='plan'?renderPlan():page==='agenda'?renderAgenda():page==='areas'?renderAreas():renderSettings()}</main></div>${page==='plan'||page==='agenda'?`<div class="mobile-actions"><button class="btn secondary" data-action="areas">${icon('grid')} Áreas</button><button class="btn primary" data-action="new">${icon('plus')} Adicionar item</button></div>`:''}`;
  bindApp();
  syncVisualMotion();
  syncUI?.refresh();
}
function areaTabs(){return `<section class="area-picker" aria-label="Áreas da vida"><div class="area-picker-head"><div><h2>Áreas</h2></div><button class="textbtn" data-action="areas" aria-label="Editar áreas">Editar</button></div><div class="area-tabs" role="group" aria-label="Escolher área"><button class="area-tab ${area==='all'?'selected':''}" data-action="area" data-id="all" aria-label="Todas as áreas" aria-pressed="${area==='all'}">${icon('grid')}<span class="area-name">Todas</span></button>${activeAreas(state).map(a=>`<button class="area-tab ${area===a.id?'selected':''}" data-action="area" data-id="${esc(a.id)}" data-drag-area="${esc(a.id)}" data-drag-label="${esc(a.name)}" aria-pressed="${area===a.id}" ${areaStyle(a)}><i class="dot"></i><span class="area-name">${esc(a.name)}</span><span class="area-grip" data-drag-handle aria-hidden="true">${icon('grip')}</span></button>`).join('')}<button class="area-tab add-area" data-action="new-area">${icon('plus')}<span class="area-name">Nova área</span></button></div></section>`}
function areaItems(){return activeItems(state).filter(t=>area==='all'||t.areaId===area)}
function controls(){const count=[status!=='all',scope!=='all',priorityFilter!=='all'].filter(Boolean).length;return `<section class="filter-panel" aria-label="Busca e filtros"><div class="filter-main"><div class="searchline">${icon('search')}<label class="sr-only" for="search-input">Buscar itens</label><input id="search-input" type="search" maxlength="200" value="${esc(query)}" placeholder="Buscar itens"></div><button class="filter-toggle ${moreFilters||count?'selected':''}" data-action="filters" aria-expanded="${moreFilters}" aria-controls="extra-filters">${icon('settings')}<span>Filtros${count?' · '+count:''}</span></button></div><div id="extra-filters" class="extra-filters" ${moreFilters?'':'hidden'}><div class="filter-field"><label for="sort-filter">Ordenar por</label><select id="sort-filter">${[['manual','Minha ordem'],['priority','Prioridade'],['date','Data'],['title','Título'],['newest','Mais recentes']].map(([v,l])=>`<option value="${v}" ${sortOrder===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="filter-field"><label for="status-filter">Status</label><select id="status-filter">${[['all','Todos'],['open','Em aberto'],['pending','Pendente'],['doing','Em andamento'],['done','Concluído'],['canceled','Cancelado']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="filter-field"><label for="scope-filter">Prazo</label><select id="scope-filter">${[['all','Com e sem data'],['overdue','Atrasados'],['today','Hoje'],['upcoming','Próximos'],['undated','Sem data']].map(([v,l])=>`<option value="${v}" ${scope===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="filter-field"><label for="priority-filter">Prioridade</label><select id="priority-filter"><option value="all" ${priorityFilter==='all'?'selected':''}>Todas</option>${PRIORITIES.map(p=>`<option value="${p.id}" ${priorityFilter===p.id?'selected':''}>${p.label}</option>`).join('')}</select></div><button class="textbtn" data-action="clear">Limpar filtros</button></div></section>`}
function pageHeading(title,subtitle){return `<div class="page-heading"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>`}
function priorityView(){return page==='plan'&&groupBy==='priority'}
function viewControls(){return `<div class="view-controls">${page==='plan'?`<div class="field"><label for="group-by">Agrupar por</label><select id="group-by">${[['none','Sem grupos'],['area','Área'],['priority','Prioridade']].map(([v,l])=>`<option value="${v}" ${groupBy===v?'selected':''}>${l}</option>`).join('')}</select></div>`:''}<div class="field"><label for="view-layout">Visualização</label><select id="view-layout"><option value="compact" ${layout==='compact'?'selected':''}>Lista compacta</option><option value="cards" ${layout==='cards'?'selected':''}>Cartões</option></select></div></div>`}
function orderToolbar(){return filtersActive()?`<div class="results-caption"><span>${filtered().length} ${filtered().length===1?'item exibido':'itens exibidos'}</span><button class="textbtn" data-action="clear">Limpar filtros</button></div>`:''}
function renderPlan(){const open=areaItems().filter(openItem).length;return `${pageHeading('Planejamento',`${open} ${open===1?'item em aberto':'itens em aberto'}`)}${viewControls()}${areaTabs()}${controls()}${orderToolbar()}<div id="task-results" class="results layout-${layout} group-${groupBy} ${priorityView()?'priority-board':''}" aria-live="polite">${planningResults()}</div>`}
function planningResults(){collections.begin();return priorityView()?renderPriorityResults():renderResults()}
function renderPriorityResults(){const items=filtered();return PRIORITIES.map(p=>{const list=items.filter(t=>openItem(t)&&t.priority===p.id);return `<section class="priority-lane priority-${p.id}" data-drop-priority="${p.id}" aria-label="Prioridade ${p.label}"><div class="priority-lane-head"><h2><span aria-hidden="true">${p.symbol}</span> ${p.label}</h2><span class="section-count">${list.length}</span><button class="iconbtn" data-action="new" data-priority="${p.id}" aria-label="Adicionar item de prioridade ${p.label}">${icon('plus')}</button></div>${list.length?itemCollection(list,'priority-'+p.id):'<p class="lane-empty">Nenhum item. Solte aqui para adicionar.</p>'}</section>`}).join('')+(!items.some(openItem)?'<p class="empty-inline">Nenhum item em aberto neste grupo de filtros.</p>':'')+(items.some(t=>!openItem(t))?`<section class="priority-closed"><h2>Encerrados</h2>${itemCollection(items.filter(t=>!openItem(t)),'closed')}</section>`:'')}
function filtered(){return selectItems(areaItems(),{status,scope,query,priority:priorityFilter,order:sortOrder,today:today()})}
function filtersActive(){return status!=='all'||scope!=='all'||!!query.trim()||priorityFilter!=='all'}
function renderResults(){const list=filtered();if(!list.length){const has=areaItems().length>0;const title=has?'Nenhum item corresponde aos filtros.':area==='all'?'Seu planejamento começa aqui.':`Nenhum item em ${esc(state.areas[area]?.name)}.`;return empty(title,has?'Ajuste a busca ou limpe os filtros para consultar os outros itens.':'Adicione um item com ou sem data. Você poderá editar tudo depois.',has?'Limpar filtros':'Adicionar primeiro item',has?'clear':'new',!activeItems(state).length)}return groupBy==='none'?itemCollection(list):activeAreas(state).filter(a=>list.some(t=>t.areaId===a.id)).map(a=>areaSection(a,list.filter(t=>t.areaId===a.id))).join('')}
function areaSection(a,items){const all=activeItems(state).filter(t=>t.areaId===a.id),done=all.filter(t=>t.status==='done').length,total=all.filter(t=>t.status!=='canceled').length;return `<section class="area-section" data-drop-area="${esc(a.id)}" ${areaStyle(a)} aria-label="Itens de ${esc(a.name)}"><div class="area-section-head"><div class="area-section-title"><i class="dot"></i><h2>${esc(a.name)}</h2><span class="section-count mono">${items.length}</span></div><div class="area-section-actions"><span class="area-progress" aria-label="${done} de ${total} itens concluídos"><span class="mini-progress"><i style="width:${total?Math.round(100*done/total):0}%"></i></span><span class="mono">${done}/${total}</span><span class="progress-label">concluídos</span></span><button class="iconbtn" data-action="new" data-area-id="${esc(a.id)}" aria-label="Adicionar item em ${esc(a.name)}" title="Adicionar item">${icon('plus')}</button></div></div>${itemCollection(items,'area-'+a.id)}</section>`}
function statusSelect(t){return `<select class="quick-status status-${t.status}" data-item-status="${esc(t.id)}" data-revision="${esc(JSON.stringify(t.revision))}" aria-label="Status de ${esc(t.title)}">${Object.entries(statusLabel).map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select>`}
function dueLabel(t){if(!t.date)return '<span class="no-date">Sem data</span>';const label=t.date===today()?'Hoje':dateLabel(t.date,{day:'2-digit',month:'2-digit',year:'numeric'});return `<span class="due-date ${openItem(t)&&t.date<today()?'late':''}">${icon('calendar')}${label}${t.time?` <span class="mono">${esc(t.time)}</span>`:''}${openItem(t)&&t.date<today()?'<span class="sr-only">, atrasado</span>':''}</span>`}
function completion(t){return `<button class="taskcheck ${t.status}" data-action="toggle" data-id="${esc(t.id)}" aria-label="${t.status==='done'?'Reabrir':'Concluir'}: ${esc(t.title)}" aria-pressed="${t.status==='done'}"><span class="checkbox">${t.status==='done'?icon('check'):t.status==='canceled'?icon('close'):t.status==='doing'?'<i></i>':''}</span></button>`}
function prioritySelect(t){const p=PRIORITIES.find(p=>p.id===t.priority);return `<select class="quick-priority priority-${t.priority}" data-item-priority="${esc(t.id)}" data-revision="${esc(JSON.stringify(t.revision))}" aria-label="Prioridade de ${esc(t.title)}">${PRIORITIES.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${x.symbol} ${x.label}</option>`).join('')}</select>`}
function dragHandle(t){return page==='agenda'?'':`<button class="drag-handle" data-drag-handle data-action="move-item" data-id="${esc(t.id)}" aria-label="Mover: ${esc(t.title)}" title="Segure para arrastar; toque para organizar">${icon('grip')}</button>`}
function compactDue(t){if(!t.date)return '<span class="no-date">Sem data</span>';const sameYear=t.date.slice(0,4)===today().slice(0,4),label=t.date===today()?'Hoje':dateLabel(t.date,{day:'2-digit',month:'2-digit',...(sameYear?{}:{year:'numeric'})});return `<time class="due-date ${openItem(t)&&t.date<today()?'late':''}" datetime="${t.date}${t.time?'T'+t.time:''}" title="${esc(t.date+(t.time?' '+t.time:''))}">${label}${t.time?` <span>${esc(t.time)}</span>`:''}</time>`}
function compactTask(t){const a=state.areas[t.areaId],showArea=groupBy!=='area'||page==='agenda';return `<article class="compact-task priority-${t.priority} ${!openItem(t)?'closed':''}" data-drag-item="${esc(t.id)}" data-drag-label="${esc(t.title)}" ${areaStyle(a)}><div class="compact-top">${completion(t)}<button class="task-title" data-action="edit" data-id="${esc(t.id)}" aria-label="Editar: ${esc(t.title)}">${esc(t.title)}</button>${dragHandle(t)}</div><div class="compact-bottom"><span class="compact-context">${showArea?`<span class="compact-area"><i class="dot"></i>${esc(a?.name)}</span>`:''}${compactDue(t)}</span><div class="compact-controls">${prioritySelect(t)}${statusSelect(t)}</div></div></article>`}
function itemCollection(items,key='all'){const {visible,remaining,step}=collections.take(key,items);return (layout==='compact'?`<div class="compact-list">${visible.map(compactTask).join('')}</div>`:`<div class="card-list">${visible.map(taskCard).join('')}</div>`)+(remaining?`<div class="collection-more"><p>${visible.length} de ${items.length} itens nesta lista</p><button class="btn secondary" data-action="show-more" data-collection="${esc(key)}">Mostrar mais ${step} ${step===1?'item':'itens'}</button></div>`:'')}
function taskCard(t){const a=state.areas[t.areaId],showArea=page==='agenda'||groupBy!=='area';return `<article class="task priority-${t.priority} ${!openItem(t)?'closed':''}" data-drag-item="${esc(t.id)}" data-drag-label="${esc(t.title)}" ${areaStyle(a)}><div class="task-top">${completion(t)}<button class="task-title" data-action="edit" data-id="${esc(t.id)}" aria-label="Editar: ${esc(t.title)}">${esc(t.title)}</button>${dragHandle(t)}</div>${t.notes?`<p class="task-note">${esc(t.notes)}</p>`:''}<div class="task-meta">${showArea?`<span class="task-area"><i class="dot"></i>${esc(a?.name)}</span>`:'<span class="sr-only">Prioridade</span>'}${prioritySelect(t)}</div><div class="task-bottom">${dueLabel(t)}${statusSelect(t)}</div></article>`}
function empty(title,text,label,action,example=false){return `<div class="empty"><span class="emptyicon">${icon('list')}</span><h2>${title}</h2><p>${text}</p><button class="btn primary" data-action="${action}">${icon(action==='new'?'plus':'settings')}${label}</button>${example?'<button class="textbtn example" data-action="example">Ver com exemplos fictícios</button>':''}</div>`}
const groupLabels={overdue:'Atrasados',today:'Hoje',upcoming:'Próximos',undated:'Sem data',closed:'Encerrados'};
function renderAgenda(){const items=filtered(),groups=groupItems(items,today());return `${pageHeading('Cronograma','Itens organizados por prazo.')}${viewControls()}${areaTabs()}${controls()}${orderToolbar()}<div id="task-results" class="results layout-${layout}" aria-live="polite">${renderTimeline(groups)}</div>`}
function renderTimeline(groups=groupItems(filtered(),today())){collections.begin();if(!Object.values(groups).some(v=>v.length))return empty('Nenhum item neste cronograma.','Adicione um item ou ajuste os filtros para consultar outros prazos.','Limpar filtros','clear');return Object.entries(groups).filter(([,items])=>items.length).map(([k,items])=>`<section class="timeline-section" aria-label="${groupLabels[k]}"><div class="timeline-heading ${k==='overdue'?'late':''}">${icon(k==='undated'?'box':k==='closed'?'check':'calendar')}<h2>${groupLabels[k]}</h2><span class="section-count mono">${items.length}</span></div>${itemCollection(selectItems(items,{order:sortOrder}),'timeline-'+k)}</section>`).join('')}
function renderAreas(){return `${pageHeading('Áreas','Organize nomes, cores e posições.')}<div class="between" style="margin-bottom:20px"><button class="textbtn" data-action="page" data-page="plan">${icon('left')} Voltar ao planejamento</button><button class="btn primary" data-action="new-area">${icon('plus')} Nova área</button></div><div class="areagrid">${activeAreas(state).map(a=>`<article class="areacard" data-drag-area="${esc(a.id)}" data-drag-label="${esc(a.name)}"><div class="between"><div class="areaicon" ${areaStyle(a)}>${icon('box')}</div><button class="iconbtn" data-action="edit-area" data-id="${esc(a.id)}" aria-label="Editar área ${esc(a.name)}">${icon('edit')}</button></div><h3>${esc(a.name)}</h3><p>${activeItems(state).filter(t=>t.areaId===a.id&&openItem(t)).length} itens em aberto</p><div class="areaactions"><button class="drag-handle" data-drag-handle aria-label="Arrastar área ${esc(a.name)}">${icon('grip')}</button><button data-action="move-area" data-id="${esc(a.id)}" data-delta="-1" aria-label="Mover ${esc(a.name)} para antes">${icon('up')}</button><button data-action="move-area" data-id="${esc(a.id)}" data-delta="1" aria-label="Mover ${esc(a.name)} para depois">${icon('down')}</button><button data-action="area" data-id="${esc(a.id)}">Abrir área ${icon('arrow')}</button></div></article>`).join('')}</div>`}
function installSection(){const info=installation.snapshot();return `<section id="retomar-install-section" class="settingscard install-section" ${info.hidden?'hidden':''} aria-labelledby="install-heading"><h2 id="install-heading">Instalar Retomar</h2><p id="install-status" role="status" aria-live="polite">${esc(info.message)}</p><button id="install-app-button" class="btn primary" data-action="install" aria-describedby="install-status" ${info.enabled?'':'disabled'}>${icon('download')}<span data-install-label>${esc(info.label)}</span></button><p class="field-help">Sem o botão habilitado, use o menu do Chrome → Adicionar à tela inicial → Instalar. No iPhone ou iPad, use Compartilhar → Adicionar à Tela de Início no Safari.</p></section>`;}
function updateInstallControls(){const section=document.querySelector('#retomar-install-section');if(!section)return;const info=installation.snapshot();section.hidden=info.hidden;document.querySelector('#install-status').textContent=info.message;const button=document.querySelector('#install-app-button');button.disabled=!info.enabled;button.querySelector('[data-install-label]').textContent=info.label;}
function backupSection(){return `<div class="settings-backup"><h3>Cópia de segurança neste aparelho</h3><p>Baixe uma cópia ou restaure um planejamento.</p><div class="settings-buttons"><button class="btn secondary" data-action="export">${icon('download')} Baixar backup</button><button class="btn secondary" data-action="import">${icon('upload')} Restaurar backup</button></div><input hidden type="file" id="backup-file" accept="application/json,.json"><details class="settings-details"><summary>Onde meus dados ficam?</summary><p>Os itens são salvos neste navegador. A conexão com o GitHub mantém uma cópia criptografada para sincronizar entre aparelhos. O JSON baixado contém os dados legíveis e não inclui credenciais.</p></details></div>`}
function renderSettings(){return `${pageHeading('Configurações','Preferências e dados do aplicativo.')}<div class="settings-stack"><section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('appearance')}</span><div><h2>Aparência</h2><p>Escolha como o Retomar aparece neste aparelho.</p></div></div><div class="settings-fields"><div class="field"><label for="accent">Cor de destaque</label><select id="accent">${[['teal','Turquesa'],['blue','Azul vivo'],['purple','Violeta'],['wine','Rosa'],['green','Verde'],['ochre','Dourado'],['coral','Coral'],['cyan','Ciano'],['indigo','Índigo'],['fuchsia','Fúcsia'],['orange','Laranja'],['lime','Lima']].map(([v,l])=>`<option value="${v}" ${(ui.accent||'teal')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="motion">Movimento</label><select id="motion"><option value="subtle" ${ui.motion!=='off'?'selected':''}>Suave</option><option value="off" ${ui.motion==='off'?'selected':''}>Desativado</option></select></div></div><p class="field-help">Alterações salvas automaticamente neste aparelho. A preferência de movimento reduzido do sistema é respeitada.</p></section>${syncUI?.card(backupSection())||''}<section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('grid')}</span><div><h2>Áreas</h2><p>Edite os nomes, as cores e a ordem das suas áreas.</p></div></div><button class="btn secondary" data-action="areas">Organizar áreas ${icon('arrow')}</button></section><section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('device')}</span><div><h2>Ajuda</h2><p>Orientações de uso.</p></div></div><details class="settings-details"><summary>Como organizar meus itens?</summary><p>Em Planejamento, escolha o agrupamento por área, por prioridade ou sem grupos. Alterne entre Lista compacta e Cartões. Segure as alças para arrastar; tocar na alça abre opções de organização. No agrupamento por prioridade, arraste entre os grupos para mudar a prioridade. Pelo teclado, use as setas na alça ou Alt + setas nas áreas.</p></details></section>${installSection()}</div><p class="version">Retomar · Versão ${VERSION}</p>`}
function bindApp(){
  document.querySelector('#app').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const previous=page+'|'+area;await action(b.dataset.action,b.dataset);if(previous!==page+'|'+area&&!document.querySelector('dialog[open]'))enterView()};
  const search=document.querySelector('#search-input');if(search)search.oninput=e=>{query=e.target.value;collections.reset();refreshResults()};
  for(const [id,set] of [['status-filter',v=>status=v],['sort-filter',v=>sortOrder=v],['scope-filter',v=>scope=v],['priority-filter',v=>priorityFilter=v]]){const el=document.getElementById(id);if(el)el.onchange=e=>{set(e.target.value);collections.reset();if(id==='sort-filter'){ui.order=sortOrder;saveUI()}refreshResults()}}
  document.querySelectorAll('[data-item-status]').forEach(el=>el.onchange=async e=>{const value=e.target.value,revision=el.dataset.revision;el.disabled=true;const ok=await mutate(s=>updateItem(s,el.dataset.itemStatus,{status:value,expectedRevision:revision},deviceId),'Status atualizado.');if(!ok){el.disabled=false;el.value=state.items[el.dataset.itemStatus]?.status||'pending'}});
  document.querySelectorAll('[data-item-priority]').forEach(el=>el.onchange=async e=>{el.disabled=true;const ok=await mutate(s=>updateItem(s,el.dataset.itemPriority,{priority:e.target.value,expectedRevision:el.dataset.revision},deviceId),'Prioridade atualizada.');if(!ok){el.disabled=false;el.value=state.items[el.dataset.itemPriority]?.priority||'normal'}});
  bindDrag(document.querySelector('#app'),{onDrop:applyDrop,onMove:moveByDelta,onAnnounce:announceMove});
  const accent=document.querySelector('#accent');if(accent)accent.onchange=e=>{ui.accent=e.target.value;document.documentElement.dataset.accent=ui.accent;saveUI()};
  const motion=document.querySelector('#motion');if(motion)motion.onchange=e=>{ui.motion=e.target.value;syncVisualMotion();saveUI()};
  const grouping=document.querySelector('#group-by');if(grouping)grouping.onchange=e=>{groupBy=e.target.value;collections.reset();ui.groupBy=groupBy;saveUI();render();document.querySelector('#group-by')?.focus()};
  const view=document.querySelector('#view-layout');if(view)view.onchange=e=>{layout=e.target.value;collections.reset();ui.layout=layout;saveUI();render();document.querySelector('#view-layout')?.focus()};
  const file=document.querySelector('#backup-file');if(file)file.onchange=importFile;
}
function refreshResults(){const results=document.querySelector('#task-results');if(results)results.innerHTML=page==='agenda'?renderTimeline():planningResults();bindApp()}
async function action(name,d={}){
  if(['page','area','areas','status','scope','undated','clear','priority-filter'].includes(name))collections.reset();
  if(name==='show-more'){const before=[...document.querySelectorAll('[data-drag-item]')].map(el=>el.dataset.dragItem);collections.more(d.collection);refreshResults();[...document.querySelectorAll('[data-drag-item]')].find(el=>!before.includes(el.dataset.dragItem))?.querySelector('.task-title')?.focus();return}
  if(name==='sync')syncUI.open();
  else if(name==='move-item')moveModal(d.id);
  else if(name==='priority-filter'){priorityFilter=priorityFilter===d.priority?'all':d.priority;render()}
  else if(name==='page'){page=d.page;render();window.scrollTo(0,0)}
  else if(name==='area'){area=d.id;if(page!=='plan'&&page!=='agenda')page='plan';render()}
  else if(name==='areas'){page='areas';render();window.scrollTo(0,0)}
  else if(name==='status'){status=d.status;render()}
  else if(name==='scope'){scope=d.scope;status='open';render()}
  else if(name==='undated'){page='plan';scope='undated';status='open';area='all';query='';render()}
  else if(name==='filters'){moreFilters=!moreFilters;render()}
  else if(name==='clear'){status='all';scope='all';priorityFilter='all';query='';render()}
  else if(name==='new'||name==='edit'){if(fatal){toast('Recupere os dados em Configurações antes de editar.');return}itemModal(name==='edit'?d.id:null,d.areaId,d.priority)}
  else if(name==='toggle'){if(fatal)return;await mutate(s=>{const t=s.items[d.id];if(!t||t.deleted)throw Error('Este item não está mais disponível.');updateItem(s,t.id,{status:t.status==='done'?'pending':'done'},deviceId)},'Alteração salva neste aparelho.')}
  else if(name==='new-area'||name==='edit-area'){if(fatal){toast('Recupere os dados antes de editar.');return}areaModal(d.id)}
  else if(name==='move-area'){await mutate(s=>{const list=activeAreas(s),i=list.findIndex(a=>a.id===d.id),j=i+Number(d.delta);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];list.forEach((a,k)=>{if(a.order!==k){a.order=k;a.revision=stamp(s,deviceId)}})})}
  else if(name==='export')exportBackup();
  else if(name==='raw'){if(repo.raw)download(repo.raw,'retomar-recuperacao-'+today()+'.txt','text/plain');else toast('Não há uma cópia corrompida disponível para baixar.')}
  else if(name==='import')document.querySelector('#backup-file').click();
  else if(name==='example')exampleModal();
  else if(name==='install')await installation.install();
}
function announceMove(message){document.querySelector('#drag-announcement').textContent=message}
function manualOrder(){sortOrder='manual';ui.order='manual';saveUI()}
function nextId(list,targetId,position){const at=list.findIndex(x=>x.id===targetId);return position==='before'?targetId:list[at+1]?.id||null}
async function applyDrop({type,id,target}){
  if(fatal||!target)return;manualOrder();
  const ok=await mutate(s=>{
    if(type==='area'){const list=activeAreas(s).filter(a=>a.id!==id);reorderAreas(s,id,nextId(list,target.id,target.position),deviceId);return}
    const moving=s.items[id];if(!moving||moving.deleted)throw Error('O item não está mais disponível.');
    let areaId=moving.areaId,priority=moving.priority,beforeId=null;
    if(target.type==='area')areaId=target.id;
    else if(target.type==='priority')priority=target.id;
    else {const other=s.items[target.id];if(!other||other.deleted)throw Error('O destino não está mais disponível.');if(priorityView())priority=other.priority;else if(groupBy==='area')areaId=other.areaId;const list=selectItems(activeItems(s).filter(t=>t.id!==id&&(priorityView()?t.priority===priority:groupBy==='area'?t.areaId===areaId:true)),{order:'manual'});beforeId=nextId(list,other.id,target.position)}
    moveItem(s,id,{areaId,priority,beforeId},deviceId);
  },type==='area'?'Ordem das áreas salva.':'Organização salva.');if(ok)announceMove(type==='area'?'Área movida.':'Item movido.');
}
async function moveByDelta({type,id,delta}){manualOrder();const ok=await mutate(s=>{const list=type==='area'?activeAreas(s):selectItems(activeItems(s).filter(t=>(priorityView()?t.priority===s.items[id]?.priority:groupBy==='area'?t.areaId===s.items[id]?.areaId:true)),{order:'manual'});const index=list.findIndex(x=>x.id===id),to=index+delta;if(index<0||to<0||to>=list.length)return;const rest=list.filter(x=>x.id!==id),beforeId=rest[to]?.id||null;if(type==='area')reorderAreas(s,id,beforeId,deviceId);else moveItem(s,id,{beforeId},deviceId)});if(ok){announceMove('Ordem atualizada.');const nodes=[...document.querySelectorAll(type==='area'?`[data-drag-area="${CSS.escape(id)}"]`:`[data-drag-item="${CSS.escape(id)}"] [data-drag-handle]`)];nodes.find(n=>n.getClientRects().length)?.focus()}}
function moveModal(id){const t=state.items[id];if(!t||t.deleted)return;const root=openModal('Organizar item',`<form id="move-item-form"><div class="formerror" role="alert"></div><p class="confirmtext">${esc(t.title)}</p><div class="field"><label for="move-area">Área</label><select id="move-area">${activeAreas(state).map(a=>`<option value="${esc(a.id)}" ${a.id===t.areaId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="move-priority">Prioridade</label><select id="move-priority">${PRIORITIES.map(p=>`<option value="${p.id}" ${p.id===t.priority?'selected':''}>${p.symbol} ${p.label}</option>`).join('')}</select></div><div class="field"><label for="move-position">Posição na área</label><select id="move-position"></select></div><p class="small muted">Também é possível segurar a alça de pontos e arrastar. Na alça, use as setas do teclado para mover.</p><div class="dialogactions"><button type="button" class="btn secondary" id="cancel-move">Cancelar</button><button class="btn primary" type="submit">Salvar organização</button></div></form>`);
  const options=()=>{const list=selectItems(activeItems(state).filter(x=>x.id!==id&&x.areaId===root.querySelector('#move-area').value),{order:'manual'});root.querySelector('#move-position').innerHTML='<option value="">No final</option>'+list.map(x=>`<option value="${esc(x.id)}">Antes de: ${esc(x.title)}</option>`).join('')};options();root.querySelector('#move-area').onchange=options;root.querySelector('#cancel-move').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;const areaId=root.querySelector('#move-area').value,priority=root.querySelector('#move-priority').value,beforeId=root.querySelector('#move-position').value||null;manualOrder();const ok=await mutate(s=>moveItem(s,id,{areaId,priority,beforeId},deviceId),'Organização salva.');if(ok)closeModal(true);else button.disabled=false});
}
function openModal(title,body,{id='',className=''}={}){returnFocus=document.activeElement;modalDirty=false;const root=document.querySelector('#dialog-root');root.innerHTML=`<dialog ${id?`id="${esc(id)}"`: ''} ${className?`class="${esc(className)}"`: ''} role="dialog" aria-labelledby="modal-title"><div class="dialoghead"><h2 id="modal-title">${title}</h2><button class="iconbtn" id="close-modal" aria-label="Fechar formulário">${icon('close')}</button></div><div class="dialogbody">${body}</div></dialog>`;const dialog=root.querySelector('dialog');root.querySelectorAll('form').forEach(bindFormErrors);dialog.showModal();root.querySelector('#close-modal').onclick=()=>closeModal();dialog.addEventListener('cancel',e=>{e.preventDefault();closeModal()});dialog.addEventListener('input',()=>modalDirty=true);dialog.addEventListener('change',()=>modalDirty=true);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});setTimeout(()=>root.querySelector('[autofocus]')?.focus(),30);syncVisualMotion();return root}
function closeModal(force=false){if(!force&&modalDirty&&!confirm('Descartar as alterações deste formulário?'))return;document.querySelector('dialog')?.close();document.querySelector('#dialog-root').innerHTML='';modalDirty=false;if(returnFocus?.isConnected)returnFocus.focus();else document.querySelector('[data-action="new"], [data-action="new-area"], .view-tab')?.focus();syncVisualMotion();syncUI?.cancelConnection();syncUI?.resume()}
function itemModal(id,defaultArea,defaultPriority){
  const existing=id?state.items[id]:null;if(id&&(!existing||existing.deleted)){toast('Este item não está disponível.');return}
  const t=existing||{title:'',notes:'',date:'',time:'',areaId:defaultArea||(area==='all'?activeAreas(state)[0].id:area),status:'pending',priority:defaultPriority||'normal'},revision=existing?JSON.stringify(existing.revision):null;
  const root=openModal(id?'Editar item':'Adicionar item',`<form id="item-form"><div class="formerror" role="alert"></div><div class="field"><label for="item-title">Título</label><input id="item-title" name="title" maxlength="200" required autofocus autocomplete="off" placeholder="Ex.: revisar o projeto"></div><div class="fieldsrow"><div class="field"><label for="item-area">Área</label><select id="item-area" name="areaId">${activeAreas(state).map(a=>`<option value="${esc(a.id)}" ${t.areaId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="item-priority">Prioridade</label><select name="priority" id="item-priority">${PRIORITIES.map(p=>`<option value="${p.id}" ${t.priority===p.id?'selected':''}>${p.symbol} ${p.label}</option>`).join('')}</select></div></div><div class="fieldsrow"><div class="field"><label for="item-date">Data <span class="muted">· opcional</span></label><input type="date" id="item-date" name="date" min="1900-01-01" max="2200-12-31" value="${esc(t.date)}"><button type="button" class="textbtn" id="clear-date">Deixar sem data</button></div><div class="field"><label for="item-time">Horário <span class="muted">· opcional</span></label><input type="time" id="item-time" name="time" value="${esc(t.time)}" ${t.date?'':'disabled'} aria-describedby="item-time-help"><small class="field-help" id="item-time-help">Escolha uma data para definir o horário.</small></div></div><details class="more-details" ${id||t.notes?'open':''}><summary>Mais detalhes</summary><div class="field"><label for="item-notes">Observações <span class="muted">· opcional</span></label><textarea id="item-notes" name="notes" maxlength="5000" placeholder="Detalhes, links ou próximos passos"></textarea></div><div class="field"><label for="item-status">Status</label><select id="item-status" name="status">${Object.entries(statusLabel).map(([k,l])=>`<option value="${k}" ${t.status===k?'selected':''}>${l}</option>`).join('')}</select></div></details><div class="dialogactions">${id?`<button type="button" class="btn danger delete" id="delete-item" aria-label="Excluir item">${icon('trash')}</button>`:''}<button type="button" class="btn secondary" id="cancel-item">Cancelar</button><button class="btn primary" type="submit">${id?'Salvar alterações':'Adicionar item'}</button></div><p class="field-help save-note">Salvo neste aparelho, mesmo sem conexão.</p></form>`);
  root.querySelector('#item-title').value=t.title;root.querySelector('#item-notes').value=t.notes;
  const form=root.querySelector('form'),dateInput=root.querySelector('#item-date'),timeInput=root.querySelector('#item-time');
  dateInput.onchange=()=>{timeInput.disabled=!dateInput.value;if(!dateInput.value)timeInput.value='';clearFieldError(timeInput)};
  root.querySelector('#clear-date').onclick=()=>{dateInput.value='';timeInput.value='';timeInput.disabled=true;clearFieldError(dateInput);clearFieldError(timeInput);modalDirty=true};
  root.querySelector('#cancel-item').onclick=()=>closeModal();
  form.onsubmit=submitOnce(async e=>{e.preventDefault();const fields=Object.fromEntries(new FormData(form));fields.title=fields.title.trim();fields.notes=(fields.notes||'').trim();fields.time=fields.date?fields.time||'':'';
    if(fields.date&&!validDate(fields.date))dateInput.setCustomValidity('Escolha uma data válida entre 1900 e 2200.');if(!checkForm(form))return;if(revision)fields.expectedRevision=revision;
    const submit=form.querySelector('[type=submit]');submit.disabled=true;const ok=await mutate(s=>{if(!s.areas[fields.areaId]||s.areas[fields.areaId].deleted)throw Error('Esta área foi removida. Reabra o formulário e escolha outra área.');updateItem(s,id||uid(),fields,deviceId)},'Item salvo neste aparelho.');if(ok)closeModal(true);else submit.disabled=false;
  });
  root.querySelector('#delete-item')?.addEventListener('click',async()=>{if(!confirm(`Excluir “${t.title}”? Você poderá desfazer por alguns segundos.`))return;const ok=await mutate(s=>{const current=s.items[id];if(JSON.stringify(current?.revision)!==revision)throw Error('O item mudou em outra janela. Reabra antes de excluir.');lastDeletion=deleteItem(s,id,deviceId)});if(ok){closeModal(true);const deleted=structuredClone(lastDeletion);toast('Item excluído.',{label:'Desfazer',run:()=>mutate(s=>undoDelete(s,deleted,deviceId),'Item restaurado.')})}});
}
function areaModal(id){const a=id?state.areas[id]:null;let color=a?.color||COLORS[activeAreas(state).length%COLORS.length];const revision=a?JSON.stringify(a.revision):null;const root=openModal(a?'Editar área':'Nova área',`<form id="area-form"><div class="formerror" role="alert"></div><div class="field"><label for="area-name">Nome da área</label><input id="area-name" name="name" maxlength="60" required autofocus placeholder="Ex.: Projetos pessoais" value="${esc(a?.name||'')}"></div><div class="field"><label>Cor de identificação</label><div class="colors" role="group" aria-label="Cor da área">${COLORS.map((c,i)=>`<button type="button" class="colorchoice ${color===c?'chosen':''}" style="--area-color:${c}" data-color="${c}" aria-label="${PALETTE[i][1]}" aria-pressed="${color===c}"></button>`).join('')}</div></div><div class="dialogactions">${a?`<button class="btn danger delete" type="button" id="remove-area" aria-label="Excluir área">${icon('trash')}</button>`:''}<button class="btn secondary" type="button" id="cancel-area">Cancelar</button><button class="btn primary" type="submit">Salvar área</button></div></form>`);root.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;modalDirty=true;root.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')})});root.querySelector('#cancel-area').onclick=()=>closeModal();root.querySelector('#area-form').onsubmit=submitOnce(async e=>{e.preventDefault();const name=root.querySelector('#area-name').value.trim();if(!checkForm(e.target))return;const submit=e.target.querySelector('[type=submit]');submit.disabled=true;const ok=await mutate(s=>{if(a&&(s.areas[id]?.deleted||JSON.stringify(s.areas[id]?.revision)!==revision))throw Error('Esta área mudou em outra janela. Reabra o formulário.');if(activeAreas(s).some(x=>x.id!==id&&areaNameKey(x.name)===areaNameKey(name)))throw Error('Já existe uma área com esse nome.');const aid=id||uid();s.areas[aid]={id:aid,name,color,order:a?s.areas[id].order:Math.max(-1,...activeAreas(s).map(x=>x.order))+1,deleted:false,revision:stamp(s,deviceId)}},'Área salva.');submit.disabled=false;if(ok)closeModal(true)});root.querySelector('#remove-area')?.addEventListener('click',()=>removeAreaModal(id))}
function removeAreaModal(id){if(activeAreas(state).length<2){document.querySelector('.formerror').textContent='Mantenha pelo menos uma área no planejamento.';return}const a=state.areas[id],count=activeItems(state).filter(t=>t.areaId===id).length;const root=openModal('Excluir área',`<form id="remove-area-form"><div class="formerror" role="alert"></div><p class="confirmtext">Excluir a área “${esc(a.name)}”? ${count?`Seus ${count} itens serão movidos para a área escolhida abaixo, incluindo os encerrados.`:'Esta área não contém itens.'}</p>${count?`<div class="field"><label for="target-area">Mover os itens para</label><select id="target-area" name="target">${activeAreas(state).filter(x=>x.id!==id).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div>`:''}<div class="dialogactions"><button class="btn secondary" type="button" id="cancel-removal">Cancelar</button><button class="btn danger" type="submit">Excluir área</button></div></form>`);root.querySelector('#cancel-removal').onclick=()=>closeModal(true);root.querySelector('form').onsubmit=submitOnce(async e=>{e.preventDefault();const target=root.querySelector('#target-area')?.value;const ok=await mutate(s=>removeArea(s,id,target,deviceId),'Área excluída; itens preservados.');if(ok)closeModal(true)})}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function exportBackup(){if(fatal){toast('Baixe a cópia para recuperação antes de exportar.');return}try{const current=repo.load();download(JSON.stringify(current,null,2),'retomar-backup-'+today()+'.json');toast('Download do backup solicitado. Confira a pasta de downloads.')}catch(e){toast(e.message)}}
async function importFile(e){const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('O arquivo excede o limite de 5 MB.');return}let candidate;try{candidate=migrateState(JSON.parse(await file.text()))}catch(err){toast('Backup não importado. '+(err instanceof SyntaxError?'O arquivo não é um JSON válido.':err.message));return}const count=activeItems(candidate).length;const root=openModal('Restaurar backup',`<div class="formerror" role="alert"></div><p class="confirmtext">Este backup contém <strong>${count} ${count===1?'item':'itens'}</strong> e <strong>${activeAreas(candidate).length} áreas</strong>. A restauração substituirá o planejamento deste aparelho.<br><br>Antes da troca, será solicitado o download de uma cópia dos dados atuais. Confira se o navegador permite o download.</p><div class="dialogactions"><button class="btn secondary" id="cancel-import">Cancelar</button><button class="btn primary" id="confirm-import">Restaurar backup</button></div>`);root.querySelector('#cancel-import').onclick=()=>closeModal(true);root.querySelector('#confirm-import').onclick=submitOnce(async e=>{e.target.disabled=true;try{if(repo.raw)download(repo.raw,'retomar-antes-da-restauracao-'+Date.now()+'.txt','text/plain');else download(JSON.stringify(repo.load(),null,2),'retomar-antes-da-restauracao-'+Date.now()+'.json');const ok=fatal?await mutate(()=>{},'Backup restaurado neste aparelho.',{replace:candidate}):await mutate(s=>Object.assign(s,restoreSnapshot(s,candidate,deviceId)),'Backup restaurado neste aparelho.');if(ok){area='all';scope='all';status='all';priorityFilter='all';query='';collections.reset();render();closeModal(true)}}catch(err){root.querySelector('.formerror').textContent=err.message}e.target.disabled=false})}
function exampleModal(){const root=openModal('Experimentar o planejamento',`<p class="confirmtext">Adicionar quatro itens fictícios às suas áreas? Eles serão salvos neste aparelho e você poderá editá-los ou excluí-los depois.</p><div class="dialogactions"><button class="btn secondary" id="cancel-example">Cancelar</button><button class="btn primary" id="confirm-example">Adicionar exemplos</button></div>`);root.querySelector('#cancel-example').onclick=()=>closeModal(true);root.querySelector('#confirm-example').onclick=submitOnce(async()=>{const ok=await mutate(s=>{const areas=activeAreas(s),find=name=>areas.find(a=>a.name===name)?.id||areas[0].id;const next=new Date();next.setDate(next.getDate()+2);for(const data of [{title:'Separar os textos da semana',areaId:find('Estudos'),date:today(),time:'',status:'pending',priority:'high',notes:'Exemplo fictício · escolha por onde começar.'},{title:'Reservar um momento para caminhar',areaId:find('Saúde'),date:today(),time:'17:00',status:'pending',priority:'normal',notes:''},{title:'Organizar uma gaveta de cada vez',areaId:find('Casa'),date:localDate(next),time:'',status:'doing',priority:'normal',notes:''},{title:'Anotar ideias para um projeto pessoal',areaId:find('Pessoal'),date:'',time:'',status:'pending',priority:'normal',notes:'Sem pressa: a data pode ficar para depois.'}])updateItem(s,uid(),data,deviceId)},'Exemplos fictícios adicionados.');if(ok)closeModal(true)})}
window.addEventListener('storage',e=>{if(e.key!==DATA_KEY)return;try{state=repo.load();fatal='';render();syncUI?.changed();if(document.querySelector('dialog'))toast('O planejamento foi atualizado em outra janela. Seu formulário foi preservado.')}catch(err){fatal=err.message;syncUI?.localFailure(err.message);render()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){try{state=repo.load();fatal=''}catch(e){fatal=e.message;syncUI?.localFailure(e.message)}render();syncUI?.resume()}});
document.addEventListener('visibilitychange',syncVisualMotion);
document.addEventListener('focusin',syncVisualMotion);
document.addEventListener('focusout',()=>queueMicrotask(syncVisualMotion));
motionPreference.addEventListener?.('change',syncVisualMotion);
window.addEventListener('beforeunload',e=>{if(modalDirty){e.preventDefault();e.returnValue=''}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./service-worker.js',{scope:'./'}).catch(()=>{});
syncUI=createSyncUI({repo,icon,esc,openModal,closeModal,toast,onExport:exportBackup,onApply:next=>{state=next;fatal='';render()},isBlocked:()=>!!fatal||modalDirty});
if(fatal)syncUI.localFailure(fatal);
render();
syncUI.start();

